"use client"

import * as React from "react"
import * as CheckboxPrimitive from "@radix-ui/react-checkbox"
import { CheckIcon } from "lucide-react"

import { cn } from "@/lib/utils"

function Checkbox({
  className,
  ...props
}: React.ComponentProps<typeof CheckboxPrimitive.Root>) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      className={cn(
        "size-4 shrink-0 rounded-lg border shadow-xs outline-none transition-all duration-500",
        "border-winedusk bg-obsidian",
        "data-[state=checked]:bg-ember data-[state=checked]:border-ember data-[state=checked]:text-obsidian",
